\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-2.6,-2.3) rectangle (2.7,2.6);
\draw[black,line width=0.5pt,->] (-2.3,0)--(2.4,0) node[below] {$x$};
\draw[black,line width=0.5pt,->] (0,-2.1)--(0,2.4) node[left] {$y$};
\draw[black,line width=0.8pt] (-2,-2)--(2,2) node[above] {$y=x$};
