% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"Source page 26 question 11b; teacher page 59"}
\begin{tikzpicture}[x=1cm,y=0.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-2.5,-3.2) rectangle (2.7,3.4);
\draw[black,line width=0.5pt,->] (-2.3,0)--(2.4,0) node[below] {$x$};
\draw[black,line width=0.5pt,->] (0,-3)--(0,3.1) node[left] {$y$};
\draw[black,line width=0.8pt,samples=100,domain=-1.65:1.65] plot (\x,{\x*\x});
\draw[black,line width=0.8pt,samples=100,domain=-1.65:1.65] plot (\x,{-\x*\x});
\node[right] at (1.9,1.2) {$y=x^2$};
\node[right] at (1.9,-1.2) {$y=-x^2$};
\end{tikzpicture}

